"""Incremental, conservative limits for private normalization staging."""

from __future__ import annotations

import stat
from dataclasses import dataclass, field
from pathlib import Path

from video_evidence_pipeline.errors import integrity_error


@dataclass(slots=True)
class StagingBudget:
    """Account generated bytes as outputs are produced, including discarded duplicates."""

    maximum_total_bytes: int
    _sizes: dict[Path, int] = field(default_factory=dict)
    total_bytes: int = 0

    @staticmethod
    def _size(path: Path, *, maximum_file_bytes: int) -> int:
        try:
            metadata = path.stat(follow_symlinks=False)
            if (
                path.is_symlink()
                or getattr(path, "is_junction", lambda: False)()
                or not stat.S_ISREG(metadata.st_mode)
                or metadata.st_size < 0
                or metadata.st_size > maximum_file_bytes
            ):
                raise integrity_error(
                    "NORMALIZED_OUTPUT_TOO_LARGE", "normalized output exceeds safe limits"
                )
            return metadata.st_size
        except OSError:
            raise integrity_error(
                "NORMALIZED_OUTPUT_INVALID", "normalized output is unavailable"
            ) from None

    def _synchronize_size(self, path: Path, *, maximum_file_bytes: int) -> int:
        size = self._size(path, maximum_file_bytes=maximum_file_bytes)
        previous = self._sizes.get(path, 0)
        if size < previous:
            raise integrity_error(
                "NORMALIZED_OUTPUT_INVALID", "normalized output changed during staging"
            )
        additional = size - previous
        if self.total_bytes + additional > self.maximum_total_bytes:
            raise integrity_error(
                "NORMALIZED_OUTPUT_TOO_LARGE", "normalized bundle exceeds safe limits"
            )
        self._sizes[path] = size
        self.total_bytes += additional
        return size

    def require_capacity(self, maximum_new_bytes: int) -> None:
        """Stop before launching another output-producing process when its bound cannot fit."""
        if (
            maximum_new_bytes <= 0
            or self.total_bytes + maximum_new_bytes > self.maximum_total_bytes
        ):
            raise integrity_error(
                "NORMALIZED_OUTPUT_TOO_LARGE", "normalized bundle exceeds safe limits"
            )

    def record_file(self, path: Path, *, maximum_file_bytes: int) -> int:
        return self._synchronize_size(path, maximum_file_bytes=maximum_file_bytes)

    def require_file_growth(
        self,
        path: Path,
        *,
        additional_bytes: int,
        maximum_file_bytes: int,
    ) -> None:
        current_size = self._synchronize_size(path, maximum_file_bytes=maximum_file_bytes)
        if (
            additional_bytes <= 0
            or current_size + additional_bytes > maximum_file_bytes
            or self.total_bytes + additional_bytes > self.maximum_total_bytes
        ):
            raise integrity_error(
                "NORMALIZED_OUTPUT_TOO_LARGE", "normalized bundle exceeds safe limits"
            )
